package com.example

/**
 * 20 completely distinct, syllabus-aligned essay question templates tailored precisely to each subject
 * (History, Buddhism, Sinhala, Civics, Geography, Commerce, Science, Math, ICT, English).
 * Guarantees zero cross-contamination and accurate subject-specific model answers for Grade 9, 10, and 11.
 */
object EssayQuestionBankTemplates {

  fun getEssaySubQuestions(
    grade: String,
    subject: String,
    cleanTheme: String,
    qIndex: Int,
    setNumber: Int
  ): List<StructuredSubQuestion> {
    val q = qIndex.coerceIn(1, 20)

    return when {
      subject.contains("ඉතිහාසය") -> getHistoryEssaySubQuestions(grade, cleanTheme, q, setNumber)
      subject.contains("බුද්ධ ධර්මය") -> getBuddhismEssaySubQuestions(grade, cleanTheme, q, setNumber)
      subject.contains("සිංහල") -> getSinhalaEssaySubQuestions(grade, cleanTheme, q, setNumber)
      subject.contains("පුරවැසි අධ්‍යාපනය") -> getCivicsEssaySubQuestions(grade, cleanTheme, q, setNumber)
      subject.contains("භූගෝල") -> getGeographyEssaySubQuestions(grade, cleanTheme, q, setNumber)
      subject.contains("ව්‍යාපාර හා ගිණුම්කරණය") -> getCommerceEssaySubQuestions(grade, cleanTheme, q, setNumber)
      subject.contains("විද්‍යාව") -> getScienceEssaySubQuestions(grade, cleanTheme, q, setNumber)
      subject.contains("ගණිතය") -> getMathEssaySubQuestions(grade, cleanTheme, q, setNumber)
      subject.contains("ICT") -> getIctEssaySubQuestions(grade, cleanTheme, q, setNumber)
      subject.contains("English") -> getEnglishEssaySubQuestions(grade, cleanTheme, q, setNumber)
      subject.contains("සෞඛ්‍ය") -> getHealthEssaySubQuestions(grade, cleanTheme, q, setNumber)
      subject.contains("කෘෂිකර්මය") -> getAgricultureEssaySubQuestions(grade, cleanTheme, q, setNumber)
      else -> getGeneralEssaySubQuestions(grade, cleanTheme, q, setNumber)
    }
  }

  private fun getScienceEssaySubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    val qv = (q + setNumber - 2) % 20 + 1
    
    // Technical Facts for Science Essay (O/L Curriculum)
    val techFacts = when {
        theme.contains("ප්‍රජනනය") -> Triple("ඩිම්බ හා ශුක්‍රාණු සංයෝජනයෙන් යුක්තාණුවක් සෑදීමේ ක්‍රියාවලිය.", "1. ඩිම්බ කෝෂ, 2. වෘෂණ", "මිනිස් ප්‍රජනක පද්ධතිය සහ හෝමෝන පාලනය.")
        theme.contains("ප්‍රකාශ සංස්ලේෂණය") -> Triple("6CO2 + 6H2O -> C6H12O6 + 6O2", "1. හරිතලව, 2. ස්ටෝමා", "ආලෝක හා අඳුරු ප්‍රතික්‍රියා යාන්ත්‍රණය.")
        theme.contains("පරිවෘත්තිය") || theme.contains("ශ්වසනය") -> Triple("C6H12O6 + 6O2 -> 6CO2 + 6H2O + ATP", "1. මයිටොකොන්ඩ්‍රියා, 2. එන්සයිම", "සෛලීය ශ්වසනය සහ ශක්ති නිෂ්පාදනය.")
        theme.contains("විද්‍යුතය") -> Triple("ඕම්ගේ නියමය: V = IR", "1. ඇමීටරය, 2. වෝල්ට්මීටරය", "ශ්‍රේණිගත සහ සමාන්තරගත පරිපථ විශ්ලේෂණය.")
        theme.contains("චලිතය") -> Triple("v = u + at සහ s = ut + ½at²", "1. ත්වරණය, 2. විස්ථාපනය", "ප්‍රවේග-කාල ප්‍රස්තාරික විශ්ලේෂණය.")
        theme.contains("පරමාණු") -> Triple("පරමාණුක ක්‍රමාංකය (Z) සහ ස්කන්ධ ක්‍රමාංකය (A)", "1. ප්‍රෝටෝන, 2. ඉලෙක්ට්‍රෝන", "ඉලෙක්ට්‍රෝන වින්‍යාසය සහ ආවර්තිතා වගුව.")
        theme.contains("ලෝහ") -> Triple("2Fe + 3O2 + xH2O -> Fe2O3.xH2O (මලකෑම)", "1. හෙමටයිට්, 2. කෝක්", "ලෝහ නිස්සාරණය සහ විඛාදනය වැළැක්වීම.")
        theme.contains("ආලෝකය") -> Triple("ස්නෙල් නියමය: n = sin i / sin r", "1. උත්තල කාච, 2. අවතල දර්පණ", "ප්‍රතිබිම්බ සෑදීම සහ ප්‍රකාශ උපකරණ.")
        theme.contains("ජාන") -> Triple("DNA ව්‍යුහය සහ මෙන්ඩල්ගේ ප්‍රවේණික නියම.", "1. වර්ණදේහ, 2. ඇලීල", "පාරම්පරික ලක්ෂණ සම්ප්‍රේෂණය.")
        theme.contains("පදාර්ථය") -> Triple("අණුක හා පරමාණුක ව්‍යුහය සහ බන්ධන.", "1. සහසංයුජ බන්ධන, 2. අයනික බන්ධන", "පදාර්ථයේ අවස්ථා විපර්යාස සහ තාපය.")
        else -> Triple("$theme හි මූලික විද්‍යාත්මක සිද්ධාන්තය.", "1. මූලික සංරචකය, 2. ක්‍රියාකාරී ඒකකය", "සම්මත විද්‍යාත්මක පරීක්ෂණ සැලසුම හා නිගමන.")
    }

    return when (qv) {
      1 -> listOf(
        StructuredSubQuestion("(A)", "$theme ($grade ශ්‍රේණිය) හි මූලික විද්‍යාත්මක සිද්ධාන්තය සහ එය තහවුරු කරන පරීක්ෂණ සැලසුම විස්තර කරන්න.", 8, "ප්‍රධාන නියමය: ${techFacts.first}. පරීක්ෂණයේදී පාලිත විචල්‍ය සහ පියවරෙන් පියවර සැලසුම.", listOf("සිද්ධාන්තය (ලකුණු 8)")),
        StructuredSubQuestion("(B)", "එම පරීක්ෂණයේ නිරීක්ෂණ ඇසුරෙන් විද්‍යාත්මක නිගමනවලට එළඹෙන ආකාරය පැහැදිලි කරන්න.", 7, "නිරීක්ෂණය: පද්ධතියේ සිදුවන විපර්යාසය. නිගමනය: ${techFacts.third} තහවුරු කිරීම.", listOf("නිගමන (ලකුණු 7)")),
        StructuredSubQuestion("(C)", "මෙම විද්‍යාත්මක දැනුම කර්මාන්ත ක්ෂේත්‍රයේදී යොදාගන්නා අවස්ථාවක් දක්වන්න.", 5, "නිෂ්පාදන ක්‍රියාවලියකදී හෝ පද්ධති පාලනයේදී යෙදීම (උදා: තත්ත්ව පාලනය).", listOf("ප්‍රායෝගික භාවිතය (ලකුණු 5)"))
      )
      2 -> listOf(
        StructuredSubQuestion("(A)", "$theme ආශ්‍රිතව හඳුනාගත හැකි ප්‍රධාන ව්‍යුහයන්ගේ (උදා: ${techFacts.second}) ක්‍රියාකාරීත්වය රචනා කරන්න.", 8, "ව්‍යුහාත්මක සැකැස්ම: ${techFacts.second}. එහි විශේෂිත වූ අනුවර්තන සහ කාර්යභාරය විග්‍රහ කිරීම.", listOf("ව්‍යුහය හා කාර්යය (ලකුණු 8)")),
        StructuredSubQuestion("(B)", "එම ව්‍යුහය පවත්වා ගැනීමට බලපාන බාහිර සාධක සාකච්ඡා කරන්න.", 7, "උෂ්ණත්වය, pH අගය හෝ පීඩනය වැනි සාධක ක්‍රියාවලියේ සීඝ්‍රතාවයට බලපාන අයුරු.", listOf("බලපාන සාධක (ලකුණු 7)")),
        StructuredSubQuestion("(C)", "අදාළ පද්ධතියේ ක්‍රියාකාරීත්වය අඩපණ වුවහොත් ඇතිවිය හැකි ගැටලු ලියන්න.", 5, "අක්‍රමිකතා සහ සෞඛ්‍ය හෝ පාරිසරික බලපෑම් (උදා: හෝමියෝස්ටැසිස් බිඳ වැටීම).", listOf("ගැටලු හඳුනාගැනීම (ලකුණු 5)"))
      )
      3 -> listOf(
        StructuredSubQuestion("(A)", "$theme ($grade) ආශ්‍රිත රසායනික ප්‍රතික්‍රියා යාන්ත්‍රණය සහ තුලිත සමීකරණ ලියන්න.", 8, "තුලිත සමීකරණය: ${techFacts.first}. ප්‍රතික්‍රියාජනක සහ ප්‍රතික්‍රියාඵල නිවැරදිව දැක්වීම.", listOf("සමීකරණ (ලකුණු 8)")),
        StructuredSubQuestion("(B)", "ප්‍රතික්‍රියා සීඝ්‍රතාව කෙරෙහි සාන්ද්‍රණය සහ උෂ්ණත්වය බලපාන අයුරු පැහැදිලි කරන්න.", 7, "අණුක ගැටුම් න්‍යාය ඇසුරෙන් විග්‍රහය: සාන්ද්‍රණය වැඩි වන විට ගැටුම් වාර ගණන වැඩි වීම.", listOf("පාලන සාධක (ලකුණු 7)")),
        StructuredSubQuestion("(C)", "කාර්මික නිෂ්පාදනවලදී (උදා: ඇමෝනියා නිෂ්පාදනය) මෙහි ඇති වැදගත්කම ලියන්න.", 5, "ඵලදාව වැඩි කරගැනීමට උත්ප්‍රේරක, ප්‍රශස්ත උෂ්ණත්වය සහ පීඩනය භාවිතය.", listOf("වැදගත්කම (ලකුණු 5)"))
