  private fun getMathEssaySubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    val qv = (q + setNumber - 2) % 20 + 1
    
    // Technical Facts for Math Essay (O/L Curriculum)
    val techFacts = when {
        theme.contains("ශ්‍රේඪි") || theme.contains("සංඛ්‍යා රටා") -> Triple("Tn = a + (n-1)d", "Sn = n/2 [2a + (n-1)d]", "සමාන්තර ශ්‍රේඪියක n වන පදය සහ එකතුව.")
        theme.contains("වර්ගජ") || theme.contains("සමීකරණ") -> Triple("x = [-b ± √(b²-4ac)] / 2a", "ax² + bx + c = 0", "වර්ගජ සමීකරණ විසඳීමේ සූත්‍රය.")
        theme.contains("පරිමාව") || theme.contains("වර්ගඵලය") -> Triple("සිලින්ඩරය: πr²h", "ගෝලය: 4/3πr³", "ඝන වස්තුවල පරිමාව සහ මතුපිට වර්ගඵලය.")
        theme.contains("සංඛ්‍යානය") -> Triple("මධ්‍යන්‍යය = Σfx / Σf", "මධ්‍යස්ථය = (n+1)/2", "දත්ත සමූහයක මධ්‍යස්ථය සහ විසිරුම.")
        theme.contains("ත්‍රිකෝණමිතිය") -> Triple("sin θ = සම්මුඛ / කර්ණය", "tan θ = සම්මුඛ / බද්ධ", "උස හා දුර සෙවීම සඳහා ත්‍රිකෝණමිතිය භාවිතය.")
        theme.contains("ජ්‍යාමිතිය") || theme.contains("ප්‍රමේය") -> Triple("පයිතගරස්: a² + b² = c²", "වෘත්ත ප්‍රමේයයන්", "ජ්‍යාමිතික සාධනය සහ ගණනය කිරීම්.")
        theme.contains("ලඝුගණක") -> Triple("logₐ (xy) = logₐ x + logₐ y", "logₐ (x/y) = logₐ x - logₐ y", "ලඝුගණක නීති සහ ගණනය කිරීම්.")
        theme.contains("අනුන්‍යාස") || theme.contains("Matrices") -> Triple("det(A) = ad - bc", "A⁻¹ = 1/det(A) [d -b; -c a]", "අනුන්‍යාස ගුණිතය සහ ප්‍රතිලෝමය.")
        theme.contains("සම්භාවිතාව") -> Triple("P(A) = n(A) / n(S)", "ස්වාධීන සිදුවීම්: P(A) × P(B)", "සිදුවීමක සම්භාවිතාව සහ ගස් සටහන්.")
