  private fun getHistoryEssaySubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    val qv = (q + setNumber - 2) % 20 + 1
    
    // Technical Facts for History Essay (O/L Curriculum)
    val techFacts = when {
        theme.contains("අනුරාධපුර") -> Triple("පණ්ඩුකාභය, දේවානම්පියතිස්ස, දුටුගැමුණු", "මහාවංශය, දීපවංශය", "පුරාණ ශ්‍රී ලංකාවේ මුල්ම සහ දීර්ඝතම රාජධානිය.")
        theme.contains("පොළොන්නරු") -> Triple("I වන විජයබාහු, මහා පරාක්‍රමබාහු", "චූලවංශය", "වාරි තාක්ෂණයේ ස්වර්ණමය යුගය.")
        theme.contains("කෝට්ටේ") -> Triple("VI වන පරාක්‍රමබාහු", "සන්දේශ සාහිත්‍යය", "මුළු දිවයිනම එක්සේසත් කළ අවසන් දේශීය පාලන යුගය.")
        theme.contains("විදේශ") || theme.contains("පෘතුගීසි") || theme.contains("ලන්දේසි") -> Triple("1505, 1658, 1796", "ත්‍රිකුණාමලය, කොළඹ, ගාල්ල", "බටහිර බලපෑම සහ යටත් විජිත පාලනය.")
        theme.contains("බ්‍රිතාන්‍ය") || theme.contains("නිදහස") -> Triple("1815, 1848, 1948", "උඩරට ගිවිසුම, ව්‍යවස්ථාපිත අරගලය", "නිදහස් අරගලය සහ පශ්චාත් නිදහස් ලංකාව.")
        else -> Triple("ඓතිහාසික සාධක", "මූලාශ්‍ර", "$theme පිළිබඳ විධිමත් ඓතිහාසික විග්‍රහය.")
    }

