        StructuredSubQuestion("(B)", "නිදහසින් පසු ශ්‍රී ලංකාව මුහුණ දුන් ප්‍රධාන අභියෝග සහ ඒවා විසඳීමට ගත් උත්සාහයන් සාකච්ඡා කරන්න.", 7, "සමාජ සාමය පවත්වා ගැනීම සහ සංහිඳියාව සඳහා ගත් ක්‍රියාමාර්ග.", listOf("පශ්චාත් නිදහස් අභියෝග")),
        StructuredSubQuestion("(C)", "ජාතික සමගියෙන් යුත් අනාගත ශ්‍රී ලංකාවක් ගොඩනැගීමට ඉතිහාසය ඉගෙනීම වැදගත් වන්නේ ඇයි?", 5, "අතීත වැරදි නිවැරදි කරගෙන සහෝදරත්වයෙන් ඉදිරියට යාම.", listOf("ඓතිහාසික දැක්ම"))
      )
      20 -> listOf(
        StructuredSubQuestion("(A)", "ශ්‍රී ලංකාවේ පුරාවිද්‍යාත්මක මූලාශ්‍ර ඉතිහාසය ලිවීමට උපකාරී වන අයුරු විග්‍රහ කරන්න.", 8, "සෙල්ලිපි, කාසි, නටබුන් මගින් ඉතිහාසයේ නිරවද්‍යතාවය තහවුරු වීම.", listOf("පුරාවිද්‍යා මූලාශ්‍ර")),
        StructuredSubQuestion("(B)", "ලිඛිත මූලාශ්‍ර (වංශකතා, සාහිත්‍ය කෘති) භාවිතයේදී සැලකිලිමත් විය යුතු කරුණු සාකච්ඡා කරන්න.", 7, "කර්තෘගේ පක්ෂපාතීත්වය සහ අතිශයෝක්තිය හඳුනා ගැනීම.", listOf("ලිඛිත මූලාශ්‍ර")),
        StructuredSubQuestion("(C)", "අපේ රටේ ඓතිහාසික උරුමය සුරැකීම පුරවැසි වගකීමක් ලෙස ඔබ දකින්නේ කෙසේද?", 5, "අනාගත පරපුර සඳහා අනන්‍යතාවය සුරැකීම.", listOf("පුරවැසි වගකීම"))
      )
      else -> listOf(
        StructuredSubQuestion("(A)", "$theme ($grade ශ්‍රේණිය) ඓතිහාසික සිදුවීමේ සමස්ත විමර්ශනයක් සහ එහි ප්‍රධාන සාධක රචනා කරන්න.", 8, "O/L විෂය නිර්දේශගත සම්මත ඓතිහාසික විග්‍රහය.", listOf("විමර්ශන රචනය (ලකුණු 8)")),
        StructuredSubQuestion("(B)", "මෙම සිදුවීම නිසා මෙරට ගමන් මඟ වෙනස් වූ ආකාරය සාකච්ඡා කරන්න.", 7, "ඓතිහාසික හැරවුම් ලක්ෂ්‍යය සහ බලපෑම.", listOf("බලපෑම (ලකුණු 7)")),
        StructuredSubQuestion("(C)", "මෙම ඓතිහාසික දැනුම අනාගත පරපුරට දායාද කිරීමේ වැදගත්කම ලියන්න.", 5, "ජාතික උරුමය සහ අනන්‍යතාවය සුරැකීම.", listOf("අනාගත වගකීම (ලකුණු 5)"))
      )
    }
  }


  private fun getBuddhismEssaySubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    val qv = (q + setNumber - 2) % 20 + 1
    
    // Technical Facts for Buddhism Essay (O/L Curriculum)
    val techFacts = when {
        theme.contains("බුද්ධ චරිතය") -> Triple("අබිනිෂ්ක්‍රමණය, දුෂ්කරක්‍රියාව, බුද්ධත්වය", "ජාතක පොත, බුද්ධවංශය", "බුදුරජාණන් වහන්සේගේ ජීවන පුවත සහ ආදර්ශ.")
        theme.contains("ධර්ම කරුණු") || theme.contains("සූත්‍ර") -> Triple("චතුරාර්ය සත්‍යය, ආර්ය අෂ්ටාංගික මාර්ගය", "ත්‍රිපිටකය", "බුදුදහමේ මූලික සිද්ධාන්ත සහ දර්ශනය.")
        theme.contains("සමාජය") || theme.contains("යුතුකම්") -> Triple("සිඟාලෝවාද සූත්‍රය, සදිසා නමස්කාරය", "පරාභව සූත්‍රය, වසල සූත්‍රය", "බෞද්ධ සමාජ දර්ශනය සහ සදාචාරය.")
        theme.contains("ශාසනය") || theme.contains("ඉතිහාසය") -> Triple("මහින්දාගමනය, සංගායනා", "අලුවිහාරය, මහා විහාරය", "බුද්ධ ශාසනයේ විකාශනය සහ ලාංකේය සංස්කෘතිය.")
        else -> Triple("බෞද්ධ මූලධර්ම", "මූලාශ්‍ර ග්‍රන්ථ", "$theme පිළිබඳ බෞද්ධ විග්‍රහය.")
    }

    return when (qv) {
      1 -> listOf(
        StructuredSubQuestion("(A)", "බුදුරජාණන් වහන්සේගේ සම්බුද්ධත්වය සහ ඒ සඳහා උන්වහන්සේ කළ අපිරිමිත කැපකිරීම සවිස්තරව විග්‍රහ කරන්න.", 8, "අබිනිෂ්ක්‍රමණය, පස්වග මහණුන් ඇසුරු කිරීම, දුෂ්කරක්‍රියාව සහ මාර පරාජය කර බුද්ධත්වය ලැබීම.", listOf("සම්බුද්ධත්වය")),
        StructuredSubQuestion("(B)", "චතුරාර්ය සත්‍යය අවබෝධ කරගැනීම මිනිසාගේ විමුක්තියට බලපාන අයුරු සාකච්ඡා කරන්න.", 7, "දුක, සමුදය, නිරෝධය සහ මාර්ගය යන සත්‍යයන් අවබෝධ කරගෙන නිවන් ලැබීම.", listOf("චතුරාර්ය සත්‍යය")),
        StructuredSubQuestion("(C)", "බුද්ධ චරිතයෙන් තරුණ පරපුරට ගත හැකි වටිනාම ආදර්ශය ලියන්න.", 5, "අචල අධිෂ්ඨානය, සත්‍ය ගවේෂණය සහ මානුෂීය ගුණාංග වර්ධනය.", listOf("ආදර්ශය"))
      )
      2 -> listOf(
        StructuredSubQuestion("(A)", "බුදුදහමේ එන 'සීල, සමාධි, ප්‍රඥා' යන ත්‍රිශික්ෂාව පුද්ගල ආධ්‍යාත්මික සංවර්ධනයට දායක වන ආකාරය විස්තර කරන්න.", 8, "කය වචනය සංවරය (ශීල), සිත එකඟ කිරීම (සමාධි) සහ යථාභූත ඥානය (පඥා) මගින් කෙලෙස් දුරු කිරීම.", listOf("ත්‍රිශික්ෂාව")),
        StructuredSubQuestion("(B)", "පංචසීල ප්‍රතිපත්තිය රක්ෂණය කිරීමෙන් සමාජයේ ඇතිවන සාමකාමී බව සාකච්ඡා කරන්න.", 7, "අවිහිංසාව, අනුන්ගේ දේ පැහැර නොගැනීම සහ සත්‍යවාදී බව තුළින් සමාජ විනය ඇති වීම.", listOf("සීලය සහ සමාජය")),
        StructuredSubQuestion("(C)", "නූතන සමාජ ගැටලු විසඳීමට ශීලයේ ඇති අදාළත්වය පෙන්වා දෙන්න.", 5, "සමාජ අපරාධ අවම වීම සහ මානසික සහනය ලැබීම.", listOf("අගය"))
      )
