  private fun getSinhalaEssaySubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    val qv = (q + setNumber - 2) % 20 + 1
    return when (qv) {
      1 -> listOf(
        StructuredSubQuestion("(A)", "$theme ($grade ශ්‍රේණිය) සාහිත්‍ය නිර්මාණයේ එන මූලික රසය සහ කතුවරයා භාවිත කළ භාෂා උපක්‍රම සවිස්තරව විචාරය කරන්න.", 8, "රූපක, උපමා සහ ධ්වනිතාර්ථ භාවිතය පිළිබඳ ගැඹුරු විග්‍රහය.", listOf("සාහිත්‍ය විචාරය")),
        StructuredSubQuestion("(B)", "මෙහි එන ප්‍රධාන චරිත නිරූපණය සහ ඒවා සමාජයට ලබාදෙන පණිවිඩය සාකච්ඡා කරන්න.", 7, "චරිත ස්වභාවය සහ මානුෂීය අගයන්.", listOf("චරිත නිරූපණය")),
        StructuredSubQuestion("(C)", "මෙම නිර්මාණය කියවීමෙන් ඔබ ලැබූ රසඥතාවය කෙටියෙන් ලියන්න.", 5, "පෞද්ගලික වින්දනය සහ අවබෝධය.", listOf("රසඥතාවය"))
      )
      2 -> listOf(
        StructuredSubQuestion("(A)", "සිංහල භාෂාවේ එන උක්ත-ආඛ්‍යාත සබඳතාව සහ ව්‍යාකරණ රීතිවල වැදගත්කම විස්තර කරන්න.", 8, "කර්තෘ කාරක සහ කර්ම කාරක වාක්‍ය රීති පිළිබඳ විග්‍රහය.", listOf("ව්‍යාකරණ")),
