  }


  private fun getCivicsEssaySubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    val qv = (q + setNumber - 2) % 20 + 1
    return when (qv) {
      1 -> listOf(
        StructuredSubQuestion("(A)", "ප්‍රජාතන්ත්‍රවාදී පාලන ක්‍රමයක මූලික ලක්ෂණ සහ එහි පවතින ජනතාවගේ පරමාධිකාරී බලය විස්තර කරන්න.", 8, "නිදහස් හා සාධාරණ මැතිවරණ, නීතියේ ආධිපත්‍යය සහ මූලික අයිතිවාසිකම්.", listOf("ප්‍රජාතන්ත්‍රවාදය (ලකුණු 8)")),
        StructuredSubQuestion("(B)", "ඍජු ප්‍රජාතන්ත්‍රවාදය සහ නියෝජිත ප්‍රජාතන්ත්‍රවාදය අතර වෙනස උදාහරණ සහිතව සාකච්ඡා කරන්න.", 7, "ජනතා සහභාගීත්වය සහ පාර්ලිමේන්තු ක්‍රමය.", listOf("පාලන ක්‍රම (ලකුණු 7)")),
        StructuredSubQuestion("(C)", "ප්‍රජාතන්ත්‍රවාදී අගයන් රැකගැනීමට පුරවැසියා සතු වගකීම ලියන්න.", 5, "ඡන්දය භාවිතය සහ විමසිලිමත් බව.", listOf("පුරවැසි වගකීම (ලකුණු 5)"))
      )
      2 -> listOf(
        StructuredSubQuestion("(A)", "ශ්‍රී ලංකා ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ 3 වන පරිච්ඡේදයේ සඳහන් මූලික අයිතිවාසිකම් සහ ඒවායේ වැදගත්කම විස්තර කරන්න.", 8, "නීතිය ඉදිරියේ සමාන වීම, භාෂණයේ නිදහස සහ ආගමික නිදහස.", listOf("මූලික අයිතිවාසිකම් (ලකුණු 8)")),
        StructuredSubQuestion("(B)", "අයිතිවාසිකම් භුක්ති විඳීමේදී යුතුකම් හා වගකීම් ඉටු කිරීමේ අවශ්‍යතාවය සාකච්ඡා කරන්න.", 7, "අන් අයගේ අයිතීන්ට ගරු කිරීම.", listOf("යුතුකම් හා වගකීම් (ලකුණු 7)")),
