  private fun getGeographyEssaySubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    val qv = (q + setNumber - 2) % 20 + 1
    return when(qv) {
        1 -> listOf(
          StructuredSubQuestion("(A)", "ශ්‍රී ලංකාවේ භූ විෂමතාවය ප්‍රධාන කලාප 3කට බෙදා එක් එක් කලාපයේ උස මට්ටම් සහ ලක්ෂණ විස්තර කරන්න.", 8, "1. වෙරළබඩ තැන්න (0-30m), 2. අන්තර් මධ්‍ය කඳුකරය (30-300m), 3. මධ්‍යම කඳුකරය (300m ට වැඩි).", listOf("භූ විෂමතාවය (ලකුණු 8)")),
          StructuredSubQuestion("(B)", "මධ්‍යම කඳුකරය ශ්‍රී ලංකාවේ ජල පෝෂක ප්‍රදේශය ලෙස හඳුන්වන්නේ ඇයි දැයි කරුණු සහිතව පැහැදිලි කරන්න.", 7, "ප්‍රධාන ගංගා සියල්ල මධ්‍යම කඳුකරයෙන් ආරම්භ වීම සහ ඉහළ වර්ෂාපතනය.", listOf("ජල පෝෂක (ලකුණු 7)")),
