  private fun getEnglishEssaySubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    val qv = (q + setNumber - 2) % 20 + 1
    return when(qv) {
        1 -> listOf(
          StructuredSubQuestion("(A)", "Write a formal letter to the Principal of your school requesting permission to organize an English Day. Include the date, time, and venue.", 8, "Format: Sender's address, Date, Recipient's address, Salutation, Subject, Body, Conclusion.", listOf("Formal Letter")),
          StructuredSubQuestion("(B)", "List three important qualities of a formal letter.", 7, "1. Formal tone, 2. Clear and concise language, 3. Proper structure.", listOf("Qualities (7 Marks)")),
          StructuredSubQuestion("(C)", "Write a suitable subject line for this letter.", 5, "Subject: Requesting permission to organize an English Day.", listOf("Subject Line (5 Marks)"))
        )
        2 -> listOf(
          StructuredSubQuestion("(A)", "Write an informal letter to your friend describing a trip you recently went on. Include details about the place and your experience.", 8, "Format: Sender's address, Date, Salutation, Body (Introduction, Content, Conclusion), Signing off.", listOf("Informal Letter (8 Marks)")),
          StructuredSubQuestion("(B)", "Mention three phrases commonly used to start an informal letter.", 7, "1. How are you?, 2. Hope you are doing well, 3. It's been a long time since I heard from you.", listOf("Phrases (7 Marks)")),
          StructuredSubQuestion("(C)", "Suggest a suitable closing for this letter.", 5, "Best regards, / Your loving friend, / Take care,", listOf("Closing (5 Marks)"))
        )
        3 -> listOf(
          StructuredSubQuestion("(A)", "Write an essay on 'The Importance of Protecting the Environment'. Use about 150-200 words.", 8, "Include: Causes of pollution, Importance of trees, Ways to protect nature, Conclusion.", listOf("Essay (8 Marks)")),
          StructuredSubQuestion("(B)", "Provide three synonyms for the word 'Environment'.", 7, "1. Nature, 2. Surroundings, 3. Habitat.", listOf("Synonyms (7 Marks)")),
          StructuredSubQuestion("(C)", "Write an effective concluding sentence for the essay.", 5, "We must act today to ensure a greener tomorrow for future generations.", listOf("Conclusion (5 Marks)"))
        )
        4 -> listOf(
          StructuredSubQuestion("(A)", "Write a speech for your school assembly on the topic 'Healthy Food Habits'.", 8, "Include: Greeting, Introduction, Benefits of healthy food, Disadvantages of junk food, Advice.", listOf("Speech (8 Marks)")),
          StructuredSubQuestion("(B)", "Identify three transition words suitable for a speech.", 7, "1. Furthermore, 2. In addition, 3. Consequently.", listOf("Transitions (7 Marks)")),
          StructuredSubQuestion("(C)", "How would you start the speech to grab the audience's attention?", 5, "By asking a question or sharing a shocking statistic about health.", listOf("Introduction (5 Marks)"))
        )
        5 -> listOf(
          StructuredSubQuestion("(A)", "Write a report for the school magazine about the Annual Sports Meet held recently.", 8, "Include: Heading, Date, Venue, Events held, Chief guest, Prize giving, Conclusion.", listOf("Report (8 Marks)")),
          StructuredSubQuestion("(B)", "State two differences between a report and a story.", 7, "1. Reports use factual data. 2. Reports usually follow a chronological order of events.", listOf("Differences (7 Marks)")),
          StructuredSubQuestion("(C)", "Suggest a catchy title for the sports meet report.", 5, "A Day of Athletic Excellence / Champions of Our School.", listOf("Title (5 Marks)"))
        )
        6 -> listOf(
          StructuredSubQuestion("(A)", "Write an article for a local newspaper on 'The Impact of Social Media on Teenagers'.", 8, "Include: Positive impacts, Negative impacts, Cyberbullying, Advice for safe use.", listOf("Article (8 Marks)")),
          StructuredSubQuestion("(B)", "List three adjectives to describe the impact of technology.", 7, "1. Revolutionary, 2. Transformative, 3. Overwhelming.", listOf("Adjectives (7 Marks)")),
          StructuredSubQuestion("(C)", "What is the main purpose of an article?", 5, "To inform, persuade, or entertain the readers about a specific topic.", listOf("Purpose (5 Marks)"))
        )
        7 -> listOf(
          StructuredSubQuestion("(A)", "Describe a picture of a 'Busy Marketplace'. Use about 100 words.", 8, "Include: People, Shops, Items being sold, Atmosphere, Colors.", listOf("Description (8 Marks)")),
          StructuredSubQuestion("(B)", "List five nouns related to a marketplace.", 7, "1. Vendors, 2. Stalls, 3. Customers, 4. Goods, 5. Bargaining.", listOf("Nouns (7 Marks)")),
          StructuredSubQuestion("(C)", "Write one sentence using an adjective-noun combination to describe the market.", 5, "The vibrant marketplace was filled with fresh vegetables and noisy crowds.", listOf("Sentence (5 Marks)"))
        )
        8 -> listOf(
          StructuredSubQuestion("(A)", "Write a story beginning with the words: 'It was a dark and stormy night...'.", 8, "Include: Character, Setting, Conflict, Resolution.", listOf("Story (8 Marks)")),
          StructuredSubQuestion("(B)", "Identify three elements of a good story.", 7, "1. Plot, 2. Characterization, 3. Climax.", listOf("Elements (7 Marks)")),
          StructuredSubQuestion("(C)", "Suggest a suitable title for your story.", 5, "The Mysterious Shadow / A Night to Remember.", listOf("Title (5 Marks)"))
        )
        9 -> listOf(
          StructuredSubQuestion("(A)", "Write a letter to a company applying for the post of 'Library Assistant'.", 8, "Include: Reason for applying, Qualifications, Experience, Availability for interview.", listOf("Job Application (8 Marks)")),
