          StructuredSubQuestion("(B)", "Explain the meaning of the proverb 'Time and tide wait for no man'.", 7, "It means that time is uncontrollable and will continue to pass regardless of our actions.", listOf("Meaning (7 Marks)")),
          StructuredSubQuestion("(C)", "List two ways a student can manage their time effectively.", 5, "1. Creating a study timetable. 2. Setting daily goals.", listOf("Time Management (5 Marks)"))
        )
        11 -> listOf(
