          StructuredSubQuestion("(B)", "Name three famous English writers and one of their works.", 7, "1. Shakespeare (Hamlet), 2. J.K. Rowling (Harry Potter), 3. Charles Dickens (Oliver Twist).", listOf("Writers (7 Marks)")),
          StructuredSubQuestion("(C)", "Why is it important to celebrate an English Day in school?", 5, "To promote language skills and appreciate English literature and culture.", listOf("Importance (5 Marks)"))
        )
        12 -> listOf(
