          StructuredSubQuestion("(B)", "Provide three synonyms for the word 'Ambition'.", 7, "1. Goal, 2. Aspiration, 3. Dream.", listOf("Synonyms (7 Marks)")),
          StructuredSubQuestion("(C)", "Why is it important to have an ambition in life?", 5, "It provides a sense of direction and motivation to work hard.", listOf("Importance (5 Marks)"))
