          StructuredSubQuestion("(B)", "Use three adjectives to describe a situation without power.", 7, "1. Chaotic, 2. Peaceful, 3. Challenging.", listOf("Adjectives (7 Marks)")),
          StructuredSubQuestion("(C)", "What was the lesson you learned from that day?", 5, "We often take modern technology for granted and should appreciate simple things.", listOf("Lesson (5 Marks)"))
        )
        18 -> listOf(
          StructuredSubQuestion("(A)", "Rewrite the following sentences in the Passive Voice: 1. He cleans the room. 2. She wrote a letter.", 8, "1. The room is cleaned by him. 2. A letter was written by her.", listOf("Passive Voice (8 Marks)")),
          StructuredSubQuestion("(B)", "Change the following into Indirect Speech: 1. 'I am happy,' she said. 2. 'Where are you?' he asked.", 7, "1. She said that she was happy. 2. He asked where I was.", listOf("Indirect Speech (7 Marks)")),
          StructuredSubQuestion("(C)", "When do we use the Passive Voice in English?", 5, "When the action is more important than the person performing it.", listOf("Usage (5 Marks)"))
        )
        19 -> listOf(
          StructuredSubQuestion("(A)", "Write a dialogue between two friends about their future plans after the O/L examination.", 8, "Include: Higher studies, Vocational training, Hobbies, Travel plans.", listOf("Dialogue (8 Marks)")),
          StructuredSubQuestion("(B)", "Identify three conversational fillers used in dialogues.", 7, "1. Well, 2. You know, 3. Actually.", listOf("Fillers (7 Marks)")),
          StructuredSubQuestion("(C)", "Write a sentence to end the dialogue politely.", 5, "Anyway, let's talk more about this later. Catch you soon!", listOf("Closing (5 Marks)"))
        )
        20 -> listOf(
          StructuredSubQuestion("(A)", "Write a speech on 'The Importance of Learning English as a Global Language'.", 8, "Include: Communication, Career opportunities, Access to information, International relations.", listOf("Speech (8 Marks)")),
          StructuredSubQuestion("(B)", "List three benefits of being bilingual.", 7, "1. Cognitive development, 2. Cultural awareness, 3. Better job prospects.", listOf("Benefits (7 Marks)")),
          StructuredSubQuestion("(C)", "Provide a strong concluding statement for this speech.", 5, "Mastering English is not just about a language; it's about opening a door to the world.", listOf("Conclusion (5 Marks)"))
        )
        else -> listOf(
          StructuredSubQuestion("(A)", "$theme ($grade Grade) unit summary and main linguistic features.", 8, "O/L Syllabus standard English analysis.", listOf("Analysis (8 Marks)")),
          StructuredSubQuestion("(B)", "Discuss how the lessons in this unit help improve your English proficiency.", 7, "Linguistic value.", listOf("Proficiency (7 Marks)")),
          StructuredSubQuestion("(C)", "Suggest one way to improve English writing skills.", 5, "Regular reading and practice writing essays.", listOf("Suggestion (5 Marks)"))
        )
    }
  }

